{"hypotheses": [
    {
        "name": "Hypothesis_1",
        "mechanism": "Companies with high earnings forecast disparity and abnormal accruals are more likely to have overstated earnings, leading to future price corrections.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "EarningsForecastDisparity"},
                {"weight": 0.5, "primitive": "AbnormalAccruals"}
            ], 
            "regime": "VIX_ABOVE_TRAILING_MEDIAN", 
            "vol_target": true
        }, 
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "lower"},
            {"type": "size_segment", "segment": "large", "direction": "stronger"},
            {"type": "correlation", "primitive": "EarningsForecastDisparity", "bound": "below", "threshold": 0.3}
        ], 
        "expected_annualized_sharpe": 0.6, 
        "expected_decay_half_life_months": 18
    },
    {
        "name": "Hypothesis_2",
        "mechanism": "Firms with high asset growth tend to be overvalued due to investor overreaction, resulting in lower future returns.",
        "expression": {
            "terms": [
                {"weight": -1.0, "primitive": "AssetGrowth"}
            ], 
            "regime": "TERM_SPREAD_NEGATIVE", 
            "vol_target": false
        }, 
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "small", "direction": "stronger"},
            {"type": "international", "region": "emerging", "direction": "same_sign"},
            {"type": "subperiod_consistency"}
        ], 
        "expected_annualized_sharpe": 0.4, 
        "expected_decay_half_life_months": null
    },
    {
        "name": "Hypothesis_3",
        "mechanism": "Companies with higher cash reserves and less tangible assets are more flexible and resilient, leading to higher future returns.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "Cash"},
                {"weight": -0.5, "primitive": "tang"}
            ], 
            "regime": "MKT_TRAILING_12M_DOWN", 
            "vol_target": true
        }, 
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "lower"},
            {"type": "size_segment", "segment": "large", "direction": "weaker"},
            {"type": "correlation", "primitive": "Cash", "bound": "below", "threshold": 0.3}
        ], 
        "expected_annualized_sharpe": 0.7, 
        "expected_decay_half_life_months": 24
    },
    {
        "name": "Hypothesis_4",
        "mechanism": "Firms with low R&D expenditure relative to their market cap and high debt issuance are less innovative and carry a higher risk, leading to lower future returns.",
        "expression": {
            "terms": [
                {"weight": -0.5, "primitive": "RD"},
                {"weight": -0.5, "primitive": "DebtIssuance"}
            ], 
            "regime": "TERM_SPREAD_POSITIVE", 
            "vol_target": false
        }, 
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "mega", "direction": "stronger"},
            {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
            {"type": "subperiod_consistency"}
        ], 
        "expected_annualized_sharpe": 0.5, 
        "expected_decay_half_life_months": null
    },
    {
        "name": "Hypothesis_5",
        "mechanism": "Firms with high net payouts and high gross profits relative to total assets are more likely to enjoy higher future returns.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "NetPayoutYield"},
                {"weight": 0.5, "primitive": "GP"}
            ], 
            "regime": "MKT_TRAILING_12M_UP", 
            "vol_target": true
        }, 
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"},
            {"type": "size_segment", "segment": "mega", "direction": "stronger"},
            {"type": "correlation", "primitive": "NetPayoutYield", "bound": "below", "threshold": 0.3}
        ], 
        "expected_annualized_sharpe": 0.8, 
        "expected_decay_half_life_months": 36
    },
    {
        "name": "Hypothesis_6",
        "mechanism": "Companies with a higher proportion of tangible assets and higher operational profitability are more likely to earn higher returns.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "tang"},
                {"weight": 0.5, "primitive": "OperProf"}
            ], 
            "regime": "VIX_BELOW_TRAILING_MEDIAN", 
            "vol_target": false
        }, 
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "small", "direction": "stronger"},
            {"type": "international", "region": "emerging", "direction": "same_sign"},
            {"type": "subperiod_consistency"}
        ], 
        "expected_annualized_sharpe": 0.6, 
        "expected_decay_half_life_months": 24
    },
    {
        "name": "Hypothesis_7",
        "mechanism": "Firms with high short interest and high analyst optimism are more susceptible to short squeezes, leading to higher future returns.",
        "expression": {
            "terms": [
                {"weight": 1.0, "primitive": "ShortInterest"},
                {"weight": 1.0, "primitive": "AOP"}
            ], 
            "regime": "TERM_SPREAD_NEGATIVE", 
            "vol_target": true
        }, 
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "lower"},
            {"type": "size_segment", "segment": "mega", "direction": "weaker"},
            {"type": "correlation", "primitive": "ShortInterest", "bound": "below", "threshold": 0.3}
        ], 
        "expected_annualized_sharpe": 0.7, 
        "expected_decay_half_life_months": 12
    },
    {
        "name": "Hypothesis_8",
        "mechanism": "Firms with low book to market ratios and high advertising expenses are more likely to be overvalued due to investor sentiment, leading to lower future returns.",
        "expression": {
            "terms": [
                {"weight": -1.0, "primitive": "BM"},
                {"weight": 1.0, "primitive": "AdExp"}
            ], 
            "regime": "TERM_SPREAD_POSITIVE", 
            "vol_target": false
        }, 
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "large", "direction": "stronger"},
            {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
            {"type": "subperiod_consistency"}
        ], 
        "expected_annualized_sharpe": 0.5, 
        "expected_decay_half_life_months": null
    }
]}
